mapper.select:
SELECT y.ID, y.CODE, y.TITLE, y.LEVEL, y.PID, y.PATH, y.ISLEAF, y.FROZEN, y.SORT, y.REMARK, y.CREATE_ID, y.CREATE_BY, y.UTC_CREATE, y.MODIFY_ID, y.MODIFY_BY, y.UTC_MODIFY, y.REVISION, s.TITLE AS PARENT_TITLE FROM SYS_POST y LEFT JOIN SYS_POST s ON s.ID = y.PID AND s.DELETED = 0
(y.DELETED = 0 OR y.DELETED IS NULL)
AND y.CODE = #{q.code,jdbcType=VARCHAR}
AND y.TITLE LIKE CONCAT('%', #{q.title,jdbcType=VARCHAR}, '%')
AND y.LEVEL = #{q.level,jdbcType=VARCHAR}
AND y.PID = #{q.pid,jdbcType=BIGINT}
ORDER BY y.SORT ASC, y.UTC_MODIFY DESC

mapper.update:
UPDATE SYS_POST
SET SORT = CASE
    WHEN ID = #{id} THEN #{newSort}
    WHEN #{newSort} < #{oldSort}
        AND SORT >= #{newSort}
        AND SORT < #{oldSort} THEN SORT + 1
    WHEN #{newSort} > #{oldSort}
        AND SORT <= #{newSort}
        AND SORT > #{oldSort} THEN SORT - 1
    ELSE SORT
END
WHERE PID = #{pid,jdbcType=BIGINT}
  AND DELETED = 0
  AND (
      (SORT BETWEEN LEAST(#{oldSort}, #{newSort}) AND GREATEST(#{oldSort}, #{newSort}))
      OR ID = #{id}
  )

UPDATE SYS_POST
SET FROZEN = #{frozen,jdbcType=INTEGER}
WHERE (
    ID = #{id,jdbcType=BIGINT}

        OR PATH LIKE CONCAT(#{path,jdbcType=VARCHAR}, '/%')

)
AND DELETED = 0
